import random
from itertools import combinations

def has_short_cycle(adj, n, max_len=6):
    # BFS from each vertex, check for cycles of length <= max_len
    for s in range(n):
        # BFS tracking parent
        dist = [-1]*n
        parent = [-1]*n
        dist[s] = 0
        queue = [s]
        while queue:
            nxt = []
            for u in queue:
                for v in adj[u]:
                    if dist[v] == -1:
                        dist[v] = dist[u]+1
                        parent[v] = u
                        if dist[v] < max_len:
                            nxt.append(v)
                    elif v != parent[u]:
                        # found a cycle of length dist[u]+dist[v]+1
                        if dist[u] + dist[v] + 1 <= max_len:
                            return True
            queue = nxt
    return False

def try_build(n=23, seed=0, max_deg=6, min_deg=3, trials=200000):
    random.seed(seed)
    # Start with empty graph; add edges greedily
    adj = [set() for _ in range(n)]
    edges = []
    pairs = list(combinations(range(n), 2))
    random.shuffle(pairs)

    def creates_short_cycle(u, v):
        # BFS from u, distance to v within 5?
        dist = {u:0}
        queue = [u]
        for _ in range(5):  # depth up to 5
            nxt = []
            for x in queue:
                for y in adj[x]:
                    if y not in dist:
                        dist[y] = dist[x]+1
                        nxt.append(y)
            queue = nxt
        if v in dist and dist[v] <= 5:
            return True
        return False

    for (u,v) in pairs:
        if len(adj[u]) >= max_deg or len(adj[v]) >= max_deg:
            continue
        if creates_short_cycle(u, v):
            continue
        adj[u].add(v)
        adj[v].add(u)
        edges.append((u,v))

    degs = [len(adj[i]) for i in range(n)]
    return adj, edges, degs

