import random

def build(n=23, seed=0, max_deg=6, min_deg=3, max_steps=5000):
    random.seed(seed)
    adj = [set() for _ in range(n)]

    def dist_le(u, v, limit):
        if u == v: return True
        visited = {u}
        frontier = [u]
        for d in range(1, limit+1):
            nxt = []
            for x in frontier:
                for y in adj[x]:
                    if y not in visited:
                        visited.add(y)
                        if y == v: return True
                        nxt.append(y)
            frontier = nxt
        return False

    def can_add(u, v):
        if u == v or v in adj[u]: return False
        if len(adj[u]) >= max_deg or len(adj[v]) >= max_deg: return False
        return not dist_le(u, v, 5)

    for step in range(max_steps):
        low = [i for i in range(n) if len(adj[i]) < min_deg]
        if not low:
            break
        u = random.choice(low)
        cands = [v for v in range(n) if can_add(u, v)]
        if not cands:
            # backtrack: remove a random edge incident to u's "neighborhood" or restart on this vertex
            # Try removing a random edge
            all_edges = [(a,b) for a in range(n) for b in adj[a] if a<b]
            if not all_edges:
                return None
            e = random.choice(all_edges)
            adj[e[0]].discard(e[1]); adj[e[1]].discard(e[0])
            continue
        v = random.choice(cands)
        adj[u].add(v); adj[v].add(u)

    degs = [len(adj[i]) for i in range(n)]
    if min(degs) < min_deg:
        return None
    edges = sorted((min(u,v), max(u,v)) for u in range(n) for v in adj[u] if u < v)
    return adj, edges, degs

def girth(adj, n):
    g = float('inf')
    for s in range(n):
        dist = [-1]*n
        parent = [-1]*n
        dist[s] = 0
        queue = [s]
        while queue:
            nxt = []
            for u in queue:
                for v in adj[u]:
                    if dist[v] == -1:
                        dist[v] = dist[u]+1
                        parent[v] = u
                        nxt.append(v)
                    elif parent[u] != v:
                        cyc = dist[u]+dist[v]+1
                        if cyc < g: g = cyc
            queue = nxt
    return g

