def lcf_graph(n, L):
    adj = [set() for _ in range(n)]
    for i in range(n):
        adj[i].add((i+1) % n)
        adj[(i+1) % n].add(i)
        off = L[i % len(L)]
        adj[i].add((i+off) % n)
        adj[(i+off) % n].add(i)
    return adj

